class Consola:
    def cmd_hola(self, nombre):
        return f"Hola, {nombre}"

    def cmd_suma(self, a, b):
        return int(a) + int(b)

def ejecutar(consola, linea):
    orden, *args = linea.split()
    metodo = getattr(consola, f"cmd_{orden}", None)   # con valor por defecto: no lanza
    if metodo is None:
        return f"Orden desconocida: {orden}"
    return metodo(*args)

c = Consola()
print(ejecutar(c, "hola Ana"))
print(ejecutar(c, "suma 2 40"))
print(ejecutar(c, "borrar todo"))

setattr(c, "prompt", ">>> ")        # igual que c.prompt = ">>> "
print(hasattr(c, "prompt"), c.prompt)
delattr(c, "prompt")                 # igual que del c.prompt
print(hasattr(c, "prompt"))

