class Config:
    """Configuración que queda congelada tras __init__."""

    def __init__(self, **opciones):
        for clave, valor in opciones.items():
            object.__setattr__(self, clave, valor)   # saltamos nuestro propio __setattr__
        object.__setattr__(self, "_congelada", True)

    def __setattr__(self, nombre, valor):
        if getattr(self, "_congelada", False):
            raise AttributeError(f"Config es de solo lectura: no se puede asignar {nombre!r}")
        object.__setattr__(self, nombre, valor)

    def __delattr__(self, nombre):
        raise AttributeError(f"Config es de solo lectura: no se puede borrar {nombre!r}")

