class Positivo:
    """Descriptor reutilizable: el valor debe ser un número > 0."""

    def __set_name__(self, owner, name):       # Python nos dice cómo nos llamamos
        self.nombre = name

    def __get__(self, instance, owner=None):
        if instance is None:                   # acceso desde la clase: Producto.precio
            return self
        try:
            return instance.__dict__[self.nombre]
        except KeyError:
            raise AttributeError(f"{self.nombre!r} no tiene valor todavía") from None

    def __set__(self, instance, value):
        if not isinstance(value, (int, float)) or value <= 0:
            raise ValueError(f"{self.nombre} debe ser un número positivo, no {value!r}")
        instance.__dict__[self.nombre] = value  # el ESTADO vive en la instancia

