class Perezoso:
    """Descriptor de NO-datos: calcula una vez y cachea en la instancia."""

    def __init__(self, funcion):
        self.funcion = funcion

    def __set_name__(self, owner, name):
        self.nombre = name

    def __get__(self, instance, owner=None):
        if instance is None:
            return self
        valor = self.funcion(instance)
        instance.__dict__[self.nombre] = valor   # la próxima vez gana el __dict__
        return valor

