from abc import ABC, abstractmethod

class Validador(ABC):
    def __set_name__(self, owner, name):
        self.privado = "_" + name

    def __get__(self, instance, owner=None):
        if instance is None:
            return self
        return getattr(instance, self.privado)

    def __set__(self, instance, value):
        self.validar(value)
        setattr(instance, self.privado, value)

    @abstractmethod
    def validar(self, value): ...

class UnoDe(Validador):
    def __init__(self, *opciones):
        self.opciones = set(opciones)

    def validar(self, value):
        if value not in self.opciones:
            raise ValueError(f"{value!r} no es una de {sorted(self.opciones)}")

class Texto(Validador):
    def __init__(self, max_len):
        self.max_len = max_len

    def validar(self, value):
        if not isinstance(value, str) or not 1 <= len(value) <= self.max_len:
            raise ValueError(f"se esperaba texto de 1 a {self.max_len} caracteres")

class Pedido:
    estado = UnoDe("nuevo", "pagado", "enviado")
    cliente = Texto(max_len=20)

    def __init__(self, cliente):
        self.cliente = cliente
        self.estado = "nuevo"

