class Propiedad:
    def __init__(self, fget=None, fset=None):
        self.fget, self.fset = fget, fset

    def __set_name__(self, owner, name):
        self.__name__ = name

    def __get__(self, instance, owner=None):
        if instance is None:
            return self
        return self.fget(instance)

    def __set__(self, instance, value):
        if self.fset is None:
            raise AttributeError(f"la propiedad {self.__name__!r} no tiene setter")
        self.fset(instance, value)

    def setter(self, fset):                 # devuelve una NUEVA propiedad con setter
        return type(self)(self.fget, fset)

class Temperatura:
    def __init__(self, celsius):
        self.celsius = celsius

    @Propiedad
    def fahrenheit(self):
        return self.celsius * 9 / 5 + 32

    @fahrenheit.setter
    def fahrenheit(self, valor):
        self.celsius = (valor - 32) * 5 / 9

t = Temperatura(100)
print(t.fahrenheit)
t.fahrenheit = 32
print(t.celsius)

from types import MethodType

class MetodoEstatico:
    def __init__(self, f):
        self.f = f

    def __get__(self, instance, owner=None):
        return self.f                          # no liga nada

class MetodoDeClase:
    def __init__(self, f):
        self.f = f

    def __get__(self, instance, owner=None):
        if owner is None:
            owner = type(instance)
        return MethodType(self.f, owner)       # liga la CLASE, no la instancia

class Fecha:
    def __init__(self, a, m, d):
        self.a, self.m, self.d = a, m, d

    @MetodoDeClase
    def desde_texto(cls, texto):
        return cls(*map(int, texto.split("-")))

    @MetodoEstatico
    def es_bisiesto(a):
        return a % 4 == 0 and (a % 100 != 0 or a % 400 == 0)

class FechaISO(Fecha):
    pass

f = FechaISO.desde_texto("2026-09-26")
print(type(f).__name__, f.a, f.m, f.d)     # cls es FechaISO: respeta la herencia
