MODELOS = {}

def registrar(cls):
    """Registra la clase por su nombre y le añade un método describir()."""
    MODELOS[cls.__name__.lower()] = cls

    def describir(self):
        campos = ", ".join(f"{k}={v!r}" for k, v in vars(self).items())
        return f"<{type(self).__name__} {campos}>"

    cls.describir = describir        # añadir métodos a una clase ya creada es legal
    return cls

@registrar
class Cliente:
    def __init__(self, nombre):
        self.nombre = nombre

