import json

class Exportador:
    formatos = {}                              # registro compartido

    def __init_subclass__(cls, /, formato, **kwargs):
        super().__init_subclass__(**kwargs)    # cooperativo: pasa el resto hacia arriba
        if formato in Exportador.formatos:
            raise ValueError(f"formato duplicado: {formato}")
        cls.formato = formato
        Exportador.formatos[formato] = cls

    def exportar(self, datos):
        raise NotImplementedError

class CSV(Exportador, formato="csv"):
    def exportar(self, datos):
        return ",".join(map(str, datos))

class JSON(Exportador, formato="json"):
    def exportar(self, datos):
        return json.dumps(datos)

def exportar(datos, formato):
    return Exportador.formatos[formato]().exportar(datos)

print(sorted(Exportador.formatos))
print(exportar([1, 2, 3], "csv"), exportar([1, 2, 3], "json"))
