class Interfaz(type):
    """Exige que las subclases implementen los métodos listados en 'requeridos'."""

    def __new__(mcls, nombre, bases, ns, **kwargs):
        cls = super().__new__(mcls, nombre, bases, ns, **kwargs)
        if bases:   # no validamos la clase raíz
            faltan = [m for m in cls.requeridos if not callable(getattr(cls, m, None))]
            if faltan:
                raise TypeError(f"{nombre} debe implementar: {', '.join(faltan)}")
        return cls

class Almacen(metaclass=Interfaz):
    requeridos = ("leer", "escribir")

class Memoria(Almacen):
    def leer(self, clave): ...
    def escribir(self, clave, valor): ...

print(type(Memoria).__name__)       # la metaclase se hereda
try:
    class Roto(Almacen):
        def leer(self, clave): ...
except TypeError as e:
    print("TypeError:", e)

class Cacheada(type):
    """Misma combinación de argumentos -> misma instancia (patrón flyweight)."""

    def __init__(cls, nombre, bases, ns, **kwargs):
        super().__init__(nombre, bases, ns, **kwargs)
        cls._cache = {}                              # cada clase, su propia caché

    def __call__(cls, *args):
        if args not in cls._cache:
            cls._cache[args] = super().__call__(*args)   # __new__ + __init__ normales
        return cls._cache[args]

class Color(metaclass=Cacheada):
    def __init__(self, nombre):
        print(f"  creando {nombre}")
        self.nombre = nombre

a = Color("rojo")
b = Color("rojo")
c = Color("azul")
print(a is b, a is c, len(Color._cache))

