import ast

class PlegarConstantes(ast.NodeTransformer):
    """Sustituye operaciones entre literales numéricos por su resultado."""
    OPERACIONES = {
        ast.Add: lambda a, b: a + b,
        ast.Sub: lambda a, b: a - b,
        ast.Mult: lambda a, b: a * b,
    }

    def visit_BinOp(self, nodo):
        self.generic_visit(nodo)                  # primero los hijos (de abajo arriba)
        operar = self.OPERACIONES.get(type(nodo.op))
        if operar and isinstance(nodo.left, ast.Constant) and isinstance(nodo.right, ast.Constant):
            nuevo = ast.Constant(operar(nodo.left.value, nodo.right.value))
            return ast.copy_location(nuevo, nodo)
        return nodo

fuente = "segundos = 24 * 60 * 60 * dias\nlimite = x + 2 * 3\nsin_plegar = dias * 24 * 60"
arbol = ast.fix_missing_locations(PlegarConstantes().visit(ast.parse(fuente)))
print(ast.unparse(arbol))

ns = {"dias": 2, "x": 1}
exec(compile(arbol, "<plegado>", "exec"), ns)
print(ns["segundos"], ns["limite"], ns["sin_plegar"])

