exercises.solution:
PREFIJO = "orden_"

class Calculadora:
    """Clase de ejemplo para probar tus funciones."""
    orden_limite = 100          # atributo NO invocable: no es una orden

    def orden_sumar(self, a, b):
        return a + b

    def orden_restar(self, a, b):
        return a - b


def ejecutar(objeto, orden, *args):
    metodo = getattr(objeto, PREFIJO + orden, None)
    if not callable(metodo):            # cubre «no existe» (None) y «no invocable»
        raise ValueError(f"Orden desconocida: {orden}")
    return metodo(*args)


def ordenes_disponibles(objeto):
    return sorted(
        nombre.removeprefix(PREFIJO)
        for nombre in dir(objeto)
        if nombre.startswith(PREFIJO) and callable(getattr(objeto, nombre))
    )

