class Robot:
    def orden_saludar(self, nombre):
        return f"Hola, {nombre}"

    def orden_apagar(self):
        return "apagado"

r = Robot()
assert ejecutar(r, "saludar", "Ana") == "Hola, Ana", "Debe llamar a orden_saludar del objeto recibido"
assert ejecutar(r, "apagar") == "apagado", "Una orden sin argumentos también debe funcionar"

try:
    ejecutar(Calculadora(), "borrar")
except ValueError as e:
    assert str(e) == "Orden desconocida: borrar", f"Mensaje incorrecto: {e!r}"
else:
    raise AssertionError("ejecutar con una orden inexistente debe lanzar ValueError")

try:
    ejecutar(Calculadora(), "limite")
except ValueError as e:
    assert str(e) == "Orden desconocida: limite", f"Mensaje incorrecto: {e!r}"
except TypeError:
    raise AssertionError("orden_limite es un entero: comprueba con callable() antes de llamarlo")
else:
    raise AssertionError("'limite' no es invocable: debe lanzar ValueError")

try:
    ejecutar(Calculadora(), "__init__")
except ValueError:
    pass
else:
    raise AssertionError("Solo se pueden invocar atributos que empiezan por 'orden_'")

class Cientifica(Calculadora):
    def orden_potencia(self, a, b):
        return a ** b

assert ordenes_disponibles(Cientifica()) == ["potencia", "restar", "sumar"], "Debe incluir las órdenes heredadas de la clase base"
assert ejecutar(Cientifica(), "potencia", 2, 10) == 1024, "ejecutar debe encontrar la orden de la subclase"
assert ejecutar(Cientifica(), "sumar", 1, 1) == 2, "ejecutar debe encontrar las órdenes heredadas"

