import inspect

VARIADICOS = (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)


def parametros_obligatorios(funcion):
    firma = inspect.signature(funcion)
    return [
        p.name
        for p in firma.parameters.values()
        if p.default is p.empty and p.kind not in VARIADICOS
    ]

