exercises.solution:
def auto_repr(cls):
    if "__repr__" in cls.__dict__:      # la clase ya trae el suyo: respetarlo
        return cls

    def __repr__(self):
        partes = [
            f"{nombre}={valor!r}"
            for nombre, valor in vars(self).items()
            if not nombre.startswith("_")
        ]
        return f"{type(self).__name__}({', '.join(partes)})"

    cls.__repr__ = __repr__
    return cls

