exercises.solution:
def crear_excepciones(esquema):
    clases = {}
    for nombre, padre in esquema.items():
        if padre is None:
            base = Exception
        elif padre in clases:
            base = clases[padre]
        else:
            raise ValueError(f"Padre desconocido: {padre}")
        clases[nombre] = type(nombre, (base,), {"__doc__": f"Error {nombre}."})
    return clases

