exercises.solution:
class ProxyRegistro:
    PROPIOS = ("accesos",)

    def __init__(self, objetivo):
        self._objetivo = objetivo        # pasa por __setattr__: empieza por _ -> proxy
        self.accesos = []                # 'accesos' -> proxy

    def __getattr__(self, nombre):
        # Solo llega aquí si la búsqueda normal en el proxy ha fallado
        valor = getattr(self._objetivo, nombre)   # si no existe: AttributeError
        self.accesos.append(nombre)               # registramos solo si hubo éxito
        return valor

    def __setattr__(self, nombre, valor):
        if nombre.startswith("_") or nombre in self.PROPIOS:
            super().__setattr__(nombre, valor)    # guardar en el propio proxy
        else:
            setattr(self._objetivo, nombre, valor)

    def __delattr__(self, nombre):
        delattr(self._objetivo, nombre)

