class Tipado:
    """Descriptor de datos que valida el tipo del valor asignado."""

    def __init__(self, tipo):
        self.tipo = tipo

    def __set_name__(self, owner, name):
        self.nombre = name

    def __get__(self, instance, owner=None):
        if instance is None:
            return self
        try:
            return instance.__dict__[self.nombre]
        except KeyError:
            raise AttributeError(f"'{self.nombre}' todavía no tiene valor") from None

    def __set__(self, instance, value):
        bool_colado = self.tipo is int and isinstance(value, bool)
        if not isinstance(value, self.tipo) or bool_colado:
            raise TypeError(
                f"{self.nombre} debe ser {self.tipo.__name__}, no {type(value).__name__}"
            )
        instance.__dict__[self.nombre] = value

