exercises.solution:
class perezoso:
    """Descriptor de no-datos: calcula una vez y cachea en la instancia."""

    def __init__(self, funcion):
        self.funcion = funcion
        self.__doc__ = funcion.__doc__

    def __set_name__(self, owner, name):
        self.nombre = name

    def __get__(self, instance, owner=None):
        if instance is None:
            return self
        valor = self.funcion(instance)          # si lanza, no se cachea nada
        instance.__dict__[self.nombre] = valor  # la próxima lectura gana el __dict__
        return valor

