exercises.solution:
class Plugin:
    registro = {}

    def __init_subclass__(cls, /, nombre=None, abstracto=False, **kwargs):
        super().__init_subclass__(**kwargs)
        if abstracto:
            return
        clave = nombre if nombre is not None else cls.__name__.lower()
        if clave in Plugin.registro:
            raise ValueError(f"Plugin duplicado: {clave}")
        cls.nombre_plugin = clave
        Plugin.registro[clave] = cls

    @classmethod
    def crear(cls, nombre, *args, **kwargs):
        return Plugin.registro[nombre](*args, **kwargs)

