exercises.solution:
import inspect

IGNORADOS = (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)


def resolver(funcion, proveedores):
    cache = {}        # nombre -> valor ya calculado en ESTA resolución
    en_curso = []     # pila de proveedores que se están resolviendo ahora

    def valor_de(nombre):
        if nombre in cache:
            return cache[nombre]
        if nombre in en_curso:
            ciclo = en_curso[en_curso.index(nombre):] + [nombre]
            raise ValueError("Dependencia circular: " + " -> ".join(ciclo))
        en_curso.append(nombre)
        cache[nombre] = llamar(proveedores[nombre])
        en_curso.pop()
        return cache[nombre]

    def llamar(f):
        argumentos = {}
        for p in inspect.signature(f).parameters.values():
            if p.kind in IGNORADOS:
                continue
            if p.name in proveedores:
                argumentos[p.name] = valor_de(p.name)
            elif p.default is p.empty:
                raise LookupError(f"Sin proveedor para '{p.name}'")
        return f(**argumentos)

    return llamar(funcion)

