exercises.solution:
class Singleton(type):
    """Metaclase: una única instancia por clase."""

    _instancias = {}      # {clase: instancia}; vive en la metaclase, no en cada clase

    def __call__(cls, *args, **kwargs):
        if cls not in Singleton._instancias:
            # type.__call__ ejecuta __new__ y __init__ como siempre
            Singleton._instancias[cls] = super().__call__(*args, **kwargs)
        return Singleton._instancias[cls]

    def reiniciar(cls):
        Singleton._instancias.pop(cls, None)

    def tiene_instancia(cls):
        return cls in Singleton._instancias

