exercises.solution:
def _es_dunder(nombre):
    return nombre.startswith("__") and nombre.endswith("__")


class EspacioVigilado(dict):
    """Espacio de nombres que prohíbe repetir nombres en el cuerpo de una clase."""

    def __init__(self, nombre_clase):
        super().__init__()
        self.nombre_clase = nombre_clase

    def __setitem__(self, clave, valor):
        if clave in self and not _es_dunder(clave):
            patron_setter = isinstance(self[clave], property) and isinstance(valor, property)
            if not patron_setter:
                raise TypeError(f"'{clave}' ya está definido en {self.nombre_clase}")
        super().__setitem__(clave, valor)


class SinRedefiniciones(type):
    @classmethod
    def __prepare__(mcls, nombre, bases, **kwargs):
        return EspacioVigilado(nombre)

    def __new__(mcls, nombre, bases, ns, **kwargs):
        return super().__new__(mcls, nombre, bases, dict(ns), **kwargs)

