exercises.solution:
import ast
import operator

OPERADORES = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
UNARIOS = {ast.UAdd: operator.pos, ast.USub: operator.neg}
MAX_EXPONENTE = 100


def evaluar(expresion, variables=None):
    try:
        arbol = ast.parse(expresion, mode="eval")
    except SyntaxError:
        raise ValueError("Sintaxis inválida") from None
    return _valor(arbol.body, variables or {})


def _valor(nodo, variables):
    match nodo:
        case ast.Constant(value=valor):
            if type(valor) not in (int, float):      # bool es subclase de int
                raise ValueError(f"Constante no permitida: {valor!r}")
            return valor
        case ast.Name(id=nombre):
            if nombre not in variables:
                raise ValueError(f"Nombre no permitido: {nombre}")
            return variables[nombre]
        case ast.UnaryOp(op=op, operand=operando) if type(op) in UNARIOS:
            return UNARIOS[type(op)](_valor(operando, variables))
        case ast.BinOp(left=izq, op=op, right=der) if type(op) in OPERADORES:
            a = _valor(izq, variables)
            b = _valor(der, variables)
            if isinstance(op, ast.Pow) and abs(b) > MAX_EXPONENTE:
                raise ValueError("Exponente demasiado grande")
            return OPERADORES[type(op)](a, b)
        case _:
            raise ValueError(f"Expresión no permitida: {type(nodo).__name__}")

