import ast
from collections import Counter


def _nombre_llamado(func):
    """'f', 'os.path.join'... o '<dinamica>' si no es una cadena de atributos sobre un nombre."""
    partes = []
    while isinstance(func, ast.Attribute):
        partes.append(func.attr)
        func = func.value
    if isinstance(func, ast.Name):
        partes.append(func.id)
        return ".".join(reversed(partes))
    return "<dinamica>"


class _Analizador(ast.NodeVisitor):
    def __init__(self):
        self.nombres = []      # pila de nombres de funciones y clases (nombre cualificado)
        self.activas = []      # pila de claves de función: la última recibe las llamadas
        self.resultado = {}

    def _visitar_cuerpo(self, nodo):
        for sentencia in nodo.body:          # solo el cuerpo: ni decoradores ni defaults
            self.visit(sentencia)

    def visit_FunctionDef(self, nodo):
        self.nombres.append(nodo.name)
        clave = ".".join(self.nombres)
        self.resultado.setdefault(clave, Counter())
        self.activas.append(clave)
        self._visitar_cuerpo(nodo)
        self.activas.pop()
        self.nombres.pop()

    visit_AsyncFunctionDef = visit_FunctionDef

    def visit_ClassDef(self, nodo):
        self.nombres.append(nodo.name)
        self._visitar_cuerpo(nodo)
        self.nombres.pop()

    def visit_Call(self, nodo):
        if self.activas:
            self.resultado[self.activas[-1]][_nombre_llamado(nodo.func)] += 1
        self.generic_visit(nodo)             # llamadas anidadas en func y argumentos


def llamadas_por_funcion(codigo):
    analizador = _Analizador()
    analizador.visit(ast.parse(codigo))      # SyntaxError se propaga
    return {nombre: dict(cuenta) for nombre, cuenta in analizador.resultado.items()}

