exercises.solution:
REQUERIDO = object()   # centinela: «este campo no tiene valor por defecto»


class Campo:
    """Descriptor de datos base: valida y guarda el valor en la instancia."""

    tipo_sql = "TEXT"
    tipo_py = object

    def __init__(self, *, default=REQUERIDO, nulo=False):
        self.default = default
        self.nulo = nulo

    def __set_name__(self, owner, name):
        self.nombre = name

    def __get__(self, instance, owner=None):
        if instance is None:
            return self
        return instance.__dict__[self.nombre]

    def __set__(self, instance, valor):
        if valor is None:
            if not self.nulo:
                raise ValueError(f"{self.nombre} no puede ser nulo")
        else:
            self.validar(valor)
        instance.__dict__[self.nombre] = valor

    def validar(self, valor):
        """Comprueba un valor que no es None; las subclases la amplían."""
        if not isinstance(valor, self.tipo_py):
            raise TypeError(f"{self.nombre} debe ser {self.tipo_py.__name__}")


class Entero(Campo):
    tipo_sql = "INTEGER"
    tipo_py = int

    def __init__(self, *, minimo=None, maximo=None, **kwargs):
        super().__init__(**kwargs)
        self.minimo = minimo
        self.maximo = maximo

    def validar(self, valor):
        if isinstance(valor, bool):                  # bool es subclase de int
            raise TypeError(f"{self.nombre} debe ser int")
        super().validar(valor)
        if (self.minimo is not None and valor < self.minimo) or (
            self.maximo is not None and valor > self.maximo
        ):
            raise ValueError(f"{self.nombre} fuera de rango")


class Texto(Campo):
    tipo_sql = "TEXT"
    tipo_py = str

    def __init__(self, *, max_len=None, **kwargs):
        super().__init__(**kwargs)
        self.max_len = max_len

    def validar(self, valor):
        super().validar(valor)
        if self.max_len is not None and len(valor) > self.max_len:
            raise ValueError(f"{self.nombre} supera {self.max_len} caracteres")


class Modelo:
    _campos = {}
    _tabla = None

    def __init_subclass__(cls, /, tabla=None, **kwargs):
        super().__init_subclass__(**kwargs)
        # __set_name__ ya se ejecutó: cada campo conoce su nombre
        campos = dict(cls._campos)                  # copia de los heredados
        for nombre, valor in vars(cls).items():     # propios, en orden de declaración
            if isinstance(valor, Campo):
                campos[nombre] = valor
        cls._campos = campos
        cls._tabla = tabla or cls.__name__.lower()

    def __init__(self, **valores):
        for nombre in valores:
            if nombre not in self._campos:
                raise TypeError(f"Campo desconocido: {nombre}")
        for nombre, campo in self._campos.items():
            if nombre in valores:
                setattr(self, nombre, valores[nombre])      # pasa por el descriptor
            elif campo.default is not REQUERIDO:
                setattr(self, nombre, campo.default)
            else:
                raise TypeError(f"Falta el campo: {nombre}")

    def a_dict(self):
        return {nombre: getattr(self, nombre) for nombre in self._campos}

    def __repr__(self):
        pares = ", ".join(f"{k}={v!r}" for k, v in self.a_dict().items())
        return f"{type(self).__name__}({pares})"

    def __eq__(self, otro):
        if type(otro) is not type(self):
            return NotImplemented
        return self.a_dict() == otro.a_dict()

    @classmethod
    def crear_tabla_sql(cls):
        columnas = ", ".join(
            f"{nombre} {campo.tipo_sql}" + ("" if campo.nulo else " NOT NULL")
            for nombre, campo in cls._campos.items()
        )
        return f"CREATE TABLE {cls._tabla} ({columnas})"

    def insertar_sql(self):
        nombres = list(self._campos)
        marcas = ", ".join("?" for _ in nombres)
        sql = f"INSERT INTO {self._tabla} ({', '.join(nombres)}) VALUES ({marcas})"
        return sql, tuple(getattr(self, n) for n in nombres)

