exercises.solution:
import ast

MENSAJES = {
    "L001": "Argumento por defecto mutable en '{}'",
    "L002": "except sin tipo captura también KeyboardInterrupt y SystemExit",
    "L003": "Compara con None usando 'is' o 'is not'",
    "L004": "Evita eval/exec: ejecutan código arbitrario",
    "L005": "Falta docstring en '{}'",
}

LITERALES_MUTABLES = (ast.List, ast.Dict, ast.Set)
CONSTRUCTORES_MUTABLES = {"list", "dict", "set"}


def _es_mutable(nodo):
    if isinstance(nodo, LITERALES_MUTABLES):
        return True
    return (
        isinstance(nodo, ast.Call)
        and isinstance(nodo.func, ast.Name)
        and nodo.func.id in CONSTRUCTORES_MUTABLES
    )


def _es_none(nodo):
    return isinstance(nodo, ast.Constant) and nodo.value is None


class Revisor(ast.NodeVisitor):
    def __init__(self):
        self.avisos = []

    def avisar(self, nodo, regla, *args):
        self.avisos.append((nodo.lineno, regla, MENSAJES[regla].format(*args)))

    def visit_FunctionDef(self, nodo):
        # kw_defaults contiene None para los solo-nombrados sin valor por defecto
        por_defecto = nodo.args.defaults + [d for d in nodo.args.kw_defaults if d is not None]
        for valor in por_defecto:
            if _es_mutable(valor):
                self.avisar(valor, "L001", nodo.name)
        if not nodo.name.startswith("_") and ast.get_docstring(nodo) is None:
            self.avisar(nodo, "L005", nodo.name)
        self.generic_visit(nodo)          # funciones anidadas, llamadas, comparaciones...

    visit_AsyncFunctionDef = visit_FunctionDef

    def visit_ExceptHandler(self, nodo):
        if nodo.type is None:
            self.avisar(nodo, "L002")
        self.generic_visit(nodo)

    def visit_Compare(self, nodo):
        operandos = [nodo.left, *nodo.comparators]
        for i, op in enumerate(nodo.ops):
            if isinstance(op, (ast.Eq, ast.NotEq)) and (
                _es_none(operandos[i]) or _es_none(operandos[i + 1])
            ):
                self.avisar(nodo, "L003")
                break                       # un aviso por comparación
        self.generic_visit(nodo)

    def visit_Call(self, nodo):
        if isinstance(nodo.func, ast.Name) and nodo.func.id in ("eval", "exec"):
            self.avisar(nodo, "L004")
        self.generic_visit(nodo)


def revisar(codigo, ignorar=()):
    try:
        arbol = ast.parse(codigo)
    except SyntaxError as error:
        return [(error.lineno, "E999", "Error de sintaxis")]
    revisor = Revisor()
    revisor.visit(arbol)
    lineas = codigo.splitlines()

    def silenciado(numero):
        return numero <= len(lineas) and lineas[numero - 1].rstrip().endswith("# noqa")

    return sorted(
        aviso
        for aviso in revisor.avisos
        if aviso[1] not in ignorar and not silenciado(aviso[0])
    )

